// CSD_RATIONALE_BEGIN
// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities. It iteratively generates tokens while ensuring grammatical validity and numerical reasoning constraints. The strategy starts with an unconstrained token generation, then refines choices based on grammar constraints and previous tokens. If a potential solution is identified (indicated by encountering an '=' token), the strategy attempts to verify the correctness of the equation.
// CSD_RATIONALE_END

var steps: nat := 0;
var currentConstrained: Prefix := [];
generated := [];
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  decreases maxSteps - steps
 {{
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;

    if next == "=" {
      // Attempt to verify the equation
      if helpers.VerifyEquation(lm, parser, generated) {
        break; // Exit loop upon successful verification
      }
    }

    // Apply grammar constraints
    if helpers.Contains(next, "+") || helpers.Contains(next, "-") || helpers.Contains(next, "*") || helpers.Contains(next, "/") {
      // Refine choices based on grammar constraints
      var refinedNext, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, currentConstrained, 1.0);
      if isValid {
        generated := generated + [refinedNext];
        steps := steps + 1;
      }
    }
 }}

